input.command:
python -I -c "
import pypdfium2 as pdfium
for name,i in [('ВК',3),('ВК',4),('ВК',19),('ПС',3),('ПС',4),('ВН',2)]:
    pdf=pdfium.PdfDocument('package/'+name+'.pdf')
    pg=pdf[i-1]; im=pg.render(scale=2).to_pil().convert('RGB'); W,H=im.size
    if name=='ВН': im=pg.render(scale=0.8).to_pil().convert('RGB')
    else: im=im.crop((int(W*0.55),int(H*0.78),W,H))
    im.save(f'work/x_{name}_{i}.png')
"

